public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt(), m = r.nextInt();
        long[] a = new long[n];
        long maxA = Long.MIN_VALUE, minA = Long.MAX_VALUE;
        // Event key sorts by (value, card, side); side bit 0 = front A, 1 = back B.
        long[] ev = new long[2 * n];
        for (int i = 0; i < n; i++) {
            a[i] = r.nextLong();
            maxA = Math.max(maxA, a[i]); minA = Math.min(minA, a[i]);
            ev[i] = (a[i] << 19) | ((long) i << 1);
        }
        for (int i = 0; i < n; i++) ev[n + i] = (r.nextLong() << 19) | ((long) i << 1) | 1;
        Arrays.sort(ev);
        int[] mask = new int[n];
        int covered = 0, front = 0, left = 0;
        long ans = maxA - minA;
        for (long e : ev) {
            long value = e >> 19;
            int i = (int) ((e >> 1) & ((1 << 18) - 1)), side = (int) (e & 1) + 1;
            if (mask[i] == 0) covered++;
            mask[i] |= side;
            if (side == 1) front++;
            while (covered == n && front >= n - m) {
                long l = ev[left];
                ans = Math.min(ans, value - (l >> 19));
                int j = (int) ((l >> 1) & ((1 << 18) - 1)), old = (int) (l & 1) + 1;
                mask[j] ^= old;
                if (mask[j] == 0) covered--;
                if (old == 1) front--;
                left++;
            }
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

