	ev := make([]int, 2*n)
	maxA, minA := 0, 1<<62
	for i := 0; i < n; i++ {
		v := readInt()
		maxA, minA = max(maxA, v), min(minA, v)
		ev[i] = v<<19 | i<<1
	}
	for i := 0; i < n; i++ {
		ev[n+i] = readInt()<<19 | i<<1 | 1
	}
	slices.Sort(ev)
	mask := make([]int, n)
	covered, front, left := 0, 0, 0
	ans := maxA - minA
	for _, e := range ev {
		value, i, side := e>>19, (e>>1)&(1<<18-1), e&1+1
		if mask[i] == 0 {
			covered++
		}
		mask[i] |= side
		if side == 1 {
			front++
		}
		for covered == n && front >= n-m {
			l := ev[left]
			ans = min(ans, value-l>>19)
			j, old := (l>>1)&(1<<18-1), l&1+1
			mask[j] ^= old
			if mask[j] == 0 {
				covered--
			}
			if old == 1 {
				front--
			}
			left++
		}
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
